from dsl import *
o="외전수로"
story("서장_외전수로",o,1,"불탄 수채",
 "아버지에게 작살창을 배우며 물 위에서 자랐다. 그 청교채가 탔다. 관선 스무 척이 밤에 물목을 막았고, 총채주 물귀신 우대강의 배는 강 건너에서 불빛만 구경했다. 아버지는 채주의 깃발을 든 채 가라앉았다. 내게 남은 것은 밑창 그을린 배 한 척과 늙은 키잡이 노 영감뿐이다. 영감이 젖은 깃발을 건져 내 무릎에 놓는다. \"소채주, 물길은 빼앗겨도 물은 남소. 어찌하시겠소.\"",
 [C("흩어진 식구부터 찾는다",O("하류의 갈대밭마다 배를 대고 이름을 불렀다. 사흘 만에 여섯이 나왔다.",alignment=AL(j=20),stats={"mind":1})),
  C("배와 사람을 사 모을 밑천부터 마련한다",O("그날 밤 관선을 따라온 소금 장수의 배를 털었다. 수채의 첫 밑천이다.",alignment=AL(s=20),silver=30)),
  C("그날 밤 관선에 물목을 열어 준 놈부터 찾는다",O("물목의 쇠사슬을 푼 것은 아버지의 술친구였다. 그는 이제 술을 마시지 못한다.",alignment=AL(m=20),stats={"external":1}))])
story("외전수로_2",o,25,"상류의 수귀",
 "두 해 동안 배 일곱 척을 모았다. 깃발을 다시 올리려면 물목이 있어야 한다. 상류를 쥔 수귀 황칠이 제 배로 나를 부른다. 갑판에 술상이 차려져 있다. \"청교채 새끼가 살아 있었구나. 네 아비하고는 술을 나눈 사이다. 그래서 묻는다. 내 밑으로 들어와 물목 하나를 받겠느냐, 아니면 내 물목을 뺏어 보겠느냐.\"",
 [C("겨뤄서 물목 하나를 건다",O("황칠이 갑판에 주저앉아 껄껄 웃었다. \"아비보다 낫다. 물목 하나 가져가라. 대신 총채주 놈을 칠 때 나를 빼놓지 마라.\"",battle="수적두목",spar=True,foe_line="\"물 위에선 내가 왕이다. 네 아비도 그건 인정했지.\"",alignment=AL(s=30,m=20),stats={"external":5,"martial":4},fame=15,flags=["수로_황칠"])),
  C("밑으로 들어가는 척 물목을 받는다",O("잔을 받았다. 황칠은 내가 언제 등을 돌릴지 셈하는 눈이었고, 나도 같은 눈이었을 것이다.",alignment=AL(s=60),silver=80,stats={"mind":3})),
  C("뱃사공들의 통행세를 줄여 준다면 손잡겠다고 한다",O("황칠이 한참 술잔을 돌렸다. \"세 번 받던 걸 한 번으로. 네 아비도 그 소리를 했다가 총채주 눈 밖에 났지.\" 그래도 잔을 부딪쳤다.",alignment=AL(j=60),stats={"mind":5},fame=15,flags=["수로_황칠","수로_사공"]))])
story("외전수로_3",o,49,"관선의 장부",
 "총채주가 어떻게 관선을 불렀는지 알았다. 강주 수군의 천호가 해마다 총채주에게서 은자 삼천 냥을 받고, 말 안 듣는 수채를 하나씩 태워 준다. 그 셈을 적은 장부가 천호의 관선에 있다. 오늘 밤 관선이 나루에 닿는다. 노 영감이 말한다. \"장부를 쥐면 총채주도 천호도 목줄이 잡히오. 다만 관선을 건드리면 수적이 아니라 역적이 되지.\"",
 [C("밤물에 숨어들어 장부만 빼낸다",O("닻줄을 타고 올라 선실 궤짝을 땄다. 젖은 몸으로 돌아오자 노 영감이 장부부터 받아 말렸다.",alignment=AL(s=50),stats={"mind":4,"martial":4},flags=["수로_장부"])),
  C("관선을 치고 장부를 빼앗는다",O("관선은 나루에 반쯤 가라앉았다. 장부는 손에 있다. 이튿날 청교채의 깃발에 관의 현상금이 붙었다.",battle="철혈대원",foe="강주 수군 백호 엄달",foe_line="\"수적이 관선에 발을 올렸다. 삼족이 무사할 줄 아느냐.\"",alignment=AL(m=60),stats={"external":6,"martial":4},flags=["수로_장부","수로_역적"])),
  C("장부를 빼내 베껴서 강가 고을마다 붙인다",O("이튿날 나루마다 천호와 총채주의 셈이 나붙었다. 천호는 사흘 만에 병을 핑계로 물러났다. 뱃사공들이 처음으로 내 배에 손을 흔들었다.",alignment=AL(j=70),stats={"mind":5},fame=25,flags=["수로_장부","수로_사공"]))])
story("외전수로_4",o,73,"전란의 강",
 "정마대전의 불이 강까지 내려왔다. 피난선이 강을 메웠고, 그 사이로 무림맹의 군량선과 신교의 병선이 오간다. 총채주는 피난선마다 뱃삯을 세 곱으로 받으라는 영을 내렸다. 못 내는 배는 뒤집으라고. 하류의 우두머리 백랑 추삼낭이 내 배로 건너와 묻는다. \"소채주, 나는 저 영이 싫어. 그렇다고 혼자 거스를 배짱도 없고. 네가 먼저 하면 따라가지.\"",
 [C("피난선을 뱃삯 없이 건네고 길잡이를 붙인다",O("청교채의 배들이 피난선 앞뒤에 섰다. 추삼낭의 흰 돛이 뒤를 이었다. 총채주의 영을 어긴 첫 수채다. 강가의 노인들이 그 깃발을 기억해 두었다.",alignment=AL(j=90),stats={"mind":6,"internal":4},fame=40,flags=["수로_피난","수로_추삼낭"])),
  C("뱃삯은 받되 곱절까지만 받는다",O("세 곱은 아니니 원망은 덜했다. 추삼낭이 어깨를 으쓱하며 따라 했다. 수채의 곳간이 찼다.",alignment=AL(s=60),silver=300,stats={"martial":4},flags=["수로_추삼낭"])),
  C("군량선과 병선을 가리지 않고 턴다",O("군량은 채에 쌓였고 병선은 강바닥에 누웠다. 맹과 신교가 한날한시에 청교채의 깃발에 현상금을 걸었다. 추삼낭은 고개를 젓고 제 배로 돌아갔다.",battle="호교대",foe="신교 병선의 호교대",foe_line="\"수적 따위가 신교의 배에 갈고리를 거느냐.\"",alignment=AL(m=70),silver=350,stats={"external":6,"martial":5},flags=["수로_약탈"]))])
story("외전수로_5",o,97,"세 물길의 회맹",
 "상류와 중류와 하류의 우두머리가 한 배에 올랐다. 스무 해 만의 회맹이다. 중류는 총채주의 심복 쌍도 방로가 쥐고 있다. 아버지의 물목이다. 방로가 탁자에 칼 두 자루를 올려놓는다. \"총채주께서 보내셨다. 청교채 깃발을 내리면 물목 하나는 남겨 주신단다. 싫으면 여기서 정하지.\"",
 [C("방로를 꺾고 아버지의 물목을 되찾는다",O("방로의 칼 두 자루가 강에 빠졌다. 중류의 배들이 청교채의 깃발 아래로 줄을 섰다.",battle="장강수적",foe="쌍도 방로",foe_line="\"네 아비 물목은 내가 잘 쓰고 있다. 물맛이 좋더군.\"",stats={"external":8,"martial":6},full_growth=True,flags=["수로_중류"])),
  C("탁자 위에 총채주와 관아의 셈을 펴 보인다",O("장부가 탁자를 한 바퀴 돌았다. 해마다 삼천 냥. 그 돈이 누구 물목에서 나갔는지 다들 알아보았다. 방로는 칼을 집지 못하고 배에서 내렸다.",alignment=AL(s=40),stats={"mind":8,"martial":4},full_growth=True,flags=["수로_중류"]),req={"flag":"수로_장부"},hidden=True),
  C("깃발을 내리는 척 총채주의 배에 오를 길을 얻는다",O("청교채의 깃발이 내려갔다. 노 영감은 그것을 개어 품에 넣었다. 방로가 웃으며 총채주의 배로 가는 뱃길을 일러 주었다.",alignment=AL(s=50,m=30),stats={"mind":6,"martial":4},full_growth=True,flags=["수로_위장"]))])
story("외전수로_끝",o,120,"총채주의 배",
 "안개 낀 강 한복판에 총채주의 큰 배가 닻을 내렸다. 그 뒤로 크고 작은 배 수백 척이 강을 덮었다. 누구 편인지는 아직 아무도 모른다. 뱃머리에 물귀신 우대강이 서 있다. \"청교채 새끼. 네 아비는 강이 뱃사공의 것이라 했다. 그래서 가라앉았다. 강은 쥐는 놈의 것이다. 올라와라. 물 위의 일은 물 위에서 끝낸다.\"",
 [C("총채주의 배에 오른다",O("우대강이 제 배의 닻줄에 걸려 강으로 떨어졌다. 큰 배에서 총채주의 깃발이 내려왔다.",battle="외전_총채주",next="강")),
  C("깃발을 내리고 강을 떠난다",O("노 영감은 아무 말 없이 키를 돌렸다. 우대강의 웃음소리가 안개 속에서 오래 따라왔다.",ending="외전수로_나루"))],
 parts={"강":part("수백 척의 배가 나를 본다. 노 영감이 낡은 청교채의 깃발을 들고 서 있다. \"소채주. 아니, 이제 뭐라 불러야 하오.\"",
   [C("총채주다. 장강은 이제 청교채의 것이다",O("깃발이 큰 배의 돛대 끝까지 올랐다.",ending="외전수로_주인")),
    C("채주면 된다. 통행세는 한 번만 받고 물목은 나눈다",O("노 영감이 웃었다. \"그 소리를 스무 해 만에 다시 듣소.\"",alignment=AL(j=40),ending="외전수로_나눔"),req={"flag_any":["수로_사공","수로_피난"]},hidden=True),
    C("깃발을 내린다. 물길은 뱃사공들의 것이다",O("청교채의 깃발이 마지막으로 접혔다.",alignment=AL(j=60),ending="외전수로_나루"))])})
enemy("외전_총채주","십대고수",hp=22500,attack=282,armor=24,name="물귀신 우대강",title="장강수로채 총채주",desc="세 물길의 우두머리 위에 앉은 장강의 주인. 관아에 은자를 바치고, 말 안 듣는 수채는 관선을 불러 태운다.",
 intro="\"강은 쥐는 놈의 것이다.\"",outro="우대강이 닻줄에 걸려 강으로 떨어졌다. 물 위로 올라온 것은 깃발뿐이다.",
 specials=[{"name":"번강도해","every":3,"mult":2.1},{"name":"닻줄 걸기","every":5,"mult":1.5,"seal":1}],
 phases=[{"hp_pct":50,"attack_mult":1.2,"text":"우대강이 갑판을 구르자 큰 배가 기운다. 발밑이 강이 된다.","quirks":[{"type":"barrier","percent":4,"every":5,"name":"물막이"}]}])
ending("외전수로_주인",o,"장강의 주인","총채주",10,"〈성명:은/는〉 총채주를 끌어내리고 장강 삼천 리 물길의 주인이 되었다.",[
 F(({"flag":"수로_약탈"},"군량선도 병선도 청교채의 깃발 앞에서는 돛을 내렸다. 강가의 아이들은 울음을 그칠 때 그 깃발 이야기를 들었다."),({"flag":"수로_피난"},"피난선을 건네준 수채가 강을 쥐었다는 말에 강가의 노인들은 통행세를 낼 때 조금 덜 투덜거렸다."),({}, "통행세는 여전히 받았다. 다만 받는 손이 바뀌었다.")),
 F(({"flag":"수로_역적"},"관은 끝내 현상금을 거두지 않았다. 〈그〉는 평생 뭍에서 자지 못했다."),({"flag":"수로_장부"},"새 천호는 부임 첫날 청교채에서 보낸 장부 사본을 받았다. 그 뒤로 관선은 물목을 막지 않았다."),({}, "관아와의 셈은 새로 시작되었다. 값은 우대강 때보다 조금 싸졌다.")),
 F(({"flag":"수로_황칠"},"수귀 황칠은 약조대로 그날 배를 끌고 왔고, 약조대로 상류를 그대로 쥐었다. 술은 해마다 한 번 같이 마셨다."),({}, "노 영감은 큰 배의 키를 잡았다. 죽는 날까지 〈그〉를 소채주라 불렀다."))])
ending("외전수로_나눔",o,"한 번 받는 뱃삯","채주",10,"〈성명:은/는〉 총채주의 자리를 없애고 물목을 나누었다. 장강의 통행세는 그날부터 한 번만 받는다.",[
 F(({}, "아버지가 가라앉으며 하려던 일이다. 스무 해가 걸렸다.")),
 F(({"flag":"수로_추삼낭"},"하류의 백랑 추삼낭이 가장 먼저 그 약조에 손도장을 찍었다. \"먼저 하면 따라간다고 했잖아.\""),({}, "세 물길의 우두머리가 한 배에서 손도장을 찍었다. 그 배는 지금도 나루에 묶여 있다.")),
 F(({"flag":"수로_피난"},"전란에 강을 건넌 사람들은 뒷날 제 자식에게 뱃사공 일을 시킬 때 청교채의 물목을 골랐다."),({}, "늙은 뱃사공들은 찢어진 돛을 깁다 말고 그 깃발이 지나가면 일어섰다.")),
 F(({}, "수적은 수적이다. 그래도 장강에서 수적이라는 말은 그 뒤로 조금 다른 뜻이 되었다."))])
ending("외전수로_나루",o,"깃발 없는 나루","나루",7,"〈성명:은/는〉 청교채의 깃발을 내렸다. 물길은 주인 없이 흘렀다.",[
 F(({}, "〈그〉는 나루에 작은 배 한 척을 묶고 사람을 건넸다. 뱃삯은 형편대로 받았다.")),
 F(({}, "노 영감은 개어 둔 깃발을 베고 잤다. 펴는 일은 없었다.")),
 F(({}, "총채주의 자리는 오래 비어 있지 않았다. 누가 앉았는지 〈그〉는 묻지 않았다."))])
rnd("수로_빚",[1,2],"아버지의 외상",
 "나루 주막의 노파가 내 얼굴을 한참 보더니 묵은 장부를 꺼낸다. \"청교채 채주 앞으로 술 서른 동이. 죽은 사람 외상은 안 받는 법인데, 자식이 살아 있으면 얘기가 다르지.\" 장부 끝에 아버지의 손도장이 찍혀 있다. 엄지가 유난히 굵다.",
 [C("외상을 갚는다",O("노파가 은자를 세어 넣고 장부의 그 장을 찢어 내게 주었다. \"네 아비 손도장이다. 가져가라.\"",alignment=AL(j=40),silver=-40,stats={"mind":4}),req={"min_silver":40}),
  C("외상 대신 주막 앞 물목을 지켜 주겠다고 한다",O("그달에 주막 앞에서 통행세를 뜯던 잡배 셋이 강에 빠졌다. 노파는 장부에 줄을 그었다.",alignment=AL(s=30),stats={"external":3,"martial":2})),
  C("아버지가 여기서 누구와 마셨는지 묻는다",O("\"수귀 황칠하고 자주 왔지. 총채주 욕을 안주로 삼았어.\" 노파가 술 한 사발을 그냥 내주었다.",stats={"mind":3,"internal":2}))],origin=o)
rnd("수로_침선",[3,4],"가라앉은 배",
 "물이 빠진 겨울, 청교채가 가라앉은 물목에 돛대 끝이 드러났다. 아버지의 배다. 숨을 참고 내려가면 선실까지 닿을 수 있다. 물은 얼음 같고 물살은 세다.",
 [C("숨을 참고 선실까지 내려간다",O("선실 벽에 아버지가 쓰던 것이 걸려 있었다. 녹은 슬었지만 날은 살아 있다. 물 위로 올라와 한참 숨을 몰아쉬었다. 숨이 전보다 길어졌다.",style_weapon=3,stats={"internal":5})),
  C("돛대에 술을 붓고 절한다",O("얼음물에 술이 퍼졌다. 내려가지는 않았다. 아버지의 것은 아버지와 함께 두기로 했다.",stats={"mind":6})),
  C("사람을 사서 배에 남은 것을 건져 판다",O("닻과 쇠붙이, 술독 몇 개. 값은 나쁘지 않았다. 노 영감은 그날 저녁을 먹지 않았다.",alignment=AL(s=40),silver=140))],origin=o)

o="외전혈승"
story("서장_외전혈승",o,1,"죽 한 그릇의 값",
 "흉년에 굶어 죽어 가던 나를 살린 것은 잿빛 가사의 승려가 내민 죽 한 그릇이었다. 죽에서는 피 냄새가 났다. 그날부터 가사를 입고 피의 경전을 외웠다. 노승들에게 선장법을 배워 열 해 동안 탁발 길을 지켰다. 오늘 교주 혈불 사도명이 나를 불렀다. 그는 눈을 감은 채 말한다. \"개조께서는 몸을 버리시며 의지를 네 곳의 옛 터에 나누어 묻으셨다. 그것을 거두어 오너라. 빼앗긴 그릇을 되찾는 날 거기에 부을 것이다. 순례는 한 사람이 해야 한다. 죽 한 그릇의 값을 아는 자가.\"",
 [C("합장하고 선장을 짚는다",O("교주가 내 이마에 피 한 방울을 찍었다. 식지 않는 피다.",alignment=AL(m=20),stats={"internal":1})),
  C("옛 터를 지키는 것이 무엇인지 묻는다",O("\"터마다 다르다. 신교의 개도 있고, 맹의 승냥이도 있고, 터 그 자체도 있다.\" 교주가 처음으로 눈을 떴다. \"묻는 것을 보니 살아서 돌아오겠구나.\"",alignment=AL(s=20),stats={"mind":1})),
  C("죽 한 그릇의 값이 어디까지인지 속으로 묻는다",O("입 밖으로는 내지 않았다. 교주는 그래도 들은 듯이 웃었다.",alignment=AL(j=20),stats={"mind":1}))])
story("외전혈승_2",o,20,"첫째 터, 마른 우물",
 "첫째 터는 폐촌의 마른 우물이다. 우물 바닥의 돌에 손바닥 자국이 찍혀 있고, 그 자국에서 백 년 묵은 한기가 올라온다. 개조의 의지다. 우물가에는 늙은 중 하나가 움막을 짓고 산다. 소림에서 나왔다는 중이다. \"백 년 동안 우리 절에서 번갈아 이 우물을 지켰네. 그 안의 것은 사람이 품을 것이 못 되네. 젊은 스님, 가사 빛이 다르다고 내쫓지는 않겠네. 차나 한잔 하고 돌아가게.\"",
 [C("노승을 꺾고 우물에 든다",O("노승은 쓰러지면서도 우물 쪽으로 손을 뻗었다. 바닥의 손바닥 자국에 손을 맞대자 한기가 팔을 타고 올라와 단전에 앉았다. 첫 조각이다.",battle="나한승",foe="우물지기 노승 법공",foe_line="\"백 년을 지킨 우물일세. 나까지는 지켜야지.\"",alignment=AL(m=60),stats={"external":4,"internal":4})),
  C("차를 마시고, 노승이 잠든 밤에 우물에 든다",O("노승은 잠든 것이 아니었을지도 모른다. 아침에 움막은 비어 있었고, 찻잔 두 개가 씻겨 엎어져 있었다. 첫 조각은 단전에 앉았다.",alignment=AL(s=50),stats={"internal":5,"mind":2})),
  C("그 안의 것이 무엇인지 노승에게 끝까지 듣는다",O("노승은 백 년 전 이 마을이 어떻게 비었는지 말해 주었다. 우물이 마른 것은 물이 아니라 사람이 말랐기 때문이라고. 듣고도 우물에 들었다. 죽 한 그릇의 값이다. 한기가 단전에 앉았다.",alignment=AL(j=50),stats={"mind":6},flags=["혈승_의심"]))])
story("외전혈승_3",o,40,"둘째 터, 덮인 비석",
 "둘째 터는 신교의 땅 안에 있다. 백 년 전 신교가 혈교를 꺾고 세운 비석 아래다. 비석에는 혈교의 글씨 위에 신교의 인장이 덮여 있다. 터를 지키는 것은 붉은 소매의 적수대다. 조장이 잿빛 가사를 알아보고 웃는다. \"산속 쥐가 여기까지 기어 나왔군. 너희 개조의 찌꺼기는 백 년째 우리 발밑에 있다.\"",
 [C("적수대를 쓸고 비석을 뽑는다",O("비석이 뽑힌 자리에서 둘째 조각이 올라왔다. 붉은 소매 넷이 그 곁에 누웠다. 백 년 만에 혈교가 신교의 땅에서 피를 본 날이다.",battle="마교척살조",foe="적수대 조장 곽표와 적수대",foe_line="\"잿빛 가사는 벗겨서 걸레로 쓴다.\"",alignment=AL(m=60),stats={"external":5,"martial":5},mastery=10)),
  C("그믐을 기다려 비석 밑을 판다",O("손톱이 다 빠졌다. 적수대는 아침에야 비석이 한 뼘 기운 것을 알았을 것이다. 둘째 조각은 단전에 앉았다.",alignment=AL(s=40),stats={"mind":4,"internal":4})),
  C("덮인 글을 손끝으로 더듬어 끝까지 읽는다",O("혈교의 글씨는 이렇게 적혀 있었다. '개조께서 연못을 파시고 첫 피를 부으셨다.' 그 아래는 신교의 인장에 덮여 손끝으로도 읽히지 않는다. 첫 피가 누구의 것이었는지. 조각은 거두었다. 손이 조금 떨렸다.",stats={"mind":6,"internal":2},flags=["혈승_비문"]))])
story("외전혈승_4",o,61,"하산",
 "교주의 격문이 붙었다. '빼앗긴 그릇을 되찾고 개조 혈마를 다시 부른다.' 백 년 만에 혈교가 산을 나선다. 첫 표적은 서촉의 신교 분타 셋이다. 좌호법 적발마두 염철이 내 어깨를 짚는다. \"순례승. 조각 둘을 품었다지. 네 몸이 곧 경전이다. 오늘 밤은 뒤에 서라. 아니면 그 조각이 싸움을 얼마나 좋아하는지 직접 보든가.\"",
 [C("선봉에 서서 분타의 문을 부순다",O("분타 셋이 하룻밤에 무너졌다. 선장이 닿는 곳마다 단전의 조각이 먼저 뛰었다. 염철이 웃었다. \"개조께서 기뻐하시는구나.\"",battle="호교대",foe="서촉 분타 호교대",foe_line="\"산속에서 백 년을 썩은 것들이 감히.\"",alignment=AL(m=70),stats={"external":6,"martial":5},fame=20)),
  C("뒤에 서서 경을 외운다",O("분타 셋이 하룻밤에 무너졌다. 경을 외우는 동안 단전의 조각이 박자를 맞췄다. 싸움이 끝나자 박자도 그쳤다.",stats={"internal":6,"mind":4})),
  C("달아나는 분타의 잡역부들을 못 본 척한다",O("밥 짓던 노파와 마구간 아이들이었다. 염철은 보았고, 아무 말도 하지 않았다. 피는 누구도 차별하지 않는다고 경전은 말한다. 그 말이 처음으로 무겁다.",alignment=AL(j=60),stats={"mind":6},flags=["혈승_의심"]))])
story("외전혈승_5",o,70,"피를 거두는 고을",
 "혈마를 부를 피가 모자라다. 강가의 고을 하나가 통째로 공양에 걸렸다. 혈위대가 고을 어귀에 피 사발을 늘어놓고, 사람들은 집 안에서 문을 걸고 떤다. 사발을 채우는 일이 내게 왔다. 셋째 조각이 이 고을 사당 밑에 묻혀 있기 때문이다. 피가 사발에 차야 조각이 깨어난다.",
 [C("경전대로 집집마다 한 사발씩 거둔다",O("죽지는 않을 만큼만 거두었다. 경전에 적힌 양이다. 아이들 것은 반 사발로 쳤다. 사당 밑에서 셋째 조각이 눈을 떴다.",alignment=AL(m=80),stats={"internal":6,"external":4},flags=["혈승_공양"])),
  C("내 피로 사발을 채운다",O("선장 끝으로 팔뚝을 그었다. 조각 둘을 품은 피는 진했다. 일곱 사발을 채우고 쓰러졌다. 혈위대는 고을의 문을 두드리지 않고 돌아갔다. 사당 밑의 조각은 내 피에도 눈을 떴다.",alignment=AL(j=70),stats={"mind":8},hp_pct=-40,flags=["혈승_의심"])),
  C("부자들에게는 피 대신 은자를 받고, 옥에 갇힌 죄수들에게서 거둔다",O("사발은 찼고 교단의 곳간도 찼다. 혈위대주는 그 셈을 마음에 들어 했다. 사당 밑에서 셋째 조각이 눈을 떴다.",alignment=AL(s=70),silver=200,stats={"internal":4},flags=["혈승_공양"]))])
story("외전혈승_6",o,88,"연못을 되찾는 밤",
 "혈교가 신교의 피 연못으로 쳐들어간다. 백 년 전 빼앗긴 그릇이다. 골짜기마다 잿빛 가사와 붉은 소매가 엉켜 쓰러진다. 넷째 조각은 연못 그 자체에 잠겨 있다. 연못가에는 우리가 있고, 우리 안에는 신교가 제물로 끌어다 놓은 아이들이 있다. 우호법 침혈수 반량이 지나가며 말한다. \"우리에는 손대지 마라. 신교가 모아 둔 것이지만 이제 우리 그릇에 든 것이다. 강림의 밤에 쓴다.\"",
 [C("연못에 들어 넷째 조각을 거둔다. 우리 쪽은 보지 않는다",O("핏물이 가슴까지 찼다. 넷째 조각이 바닥에서 올라와 단전에 앉았다. 넷이 모이자 몸 안에서 무엇인가 눈을 뜨려 한다.",alignment=AL(m=70),stats={"internal":8,"external":3},full_growth=True)),
  C("조각을 거두고, 우리의 아이들에게 죽을 쑤어 먹인다",O("솥을 걸고 죽을 쑤었다. 피는 넣지 않았다. 아이 하나가 묻는다. \"스님, 우리 언제 나가요?\" 답하지 못했다. 죽 그릇을 받던 날의 내가 같은 얼굴이었을 것이다.",alignment=AL(j=50),stats={"mind":8,"internal":4},full_growth=True,flags=["혈승_죽","혈승_의심"])),
  C("연못을 지키던 신교의 심판자와 맞선다",O("심판자가 연못가에 쓰러졌다. 백 년 동안 이 연못에 사람을 던진 손이다. 넷째 조각이 바닥에서 올라와 단전에 앉았다.",battle="마교심판자",foe_line="\"잿빛 쥐가 조각을 품었구나. 먹이인지 사냥꾼인지 보자.\"",alignment=AL(m=40),stats={"external":8,"martial":6},full_growth=True,flags=["혈승_심판자"]))])
story("외전혈승_7",o,96,"강림의 밤",
 "피 연못이 끓는다. 제단 앞에 교주 혈불 사도명이 서 있고 좌우에 두 호법이 섰다. 네 조각이 단전에서 한 덩이로 뭉쳐 연못 쪽으로 나를 끈다. 교주가 손을 내민다. \"순례승. 부어라. 네가 거두어 온 것을 네 손으로.\" 연못가 우리에서 아이들이 운다. 골짜기 아래에서는 신교의 탈환대가 올라오는 횃불이 보인다.",
 [C("의지를 연못에 붓는다",O("손바닥을 연못에 담갔다.",next="강림")),
  C("붓기 전에 우리의 빗장부터 내리친다",O("반량이 연못가에 쓰러졌다. 우리의 빗장이 선장 아래 부러졌다. 아이들이 쏟아져 나온다.",battle="외전_반량",foe_line="\"그릇에 든 것에 손대지 말라 했다, 순례승.\"",alignment=AL(j=80),next="문"))],
 parts={
  "강림":part("네 조각이 한꺼번에 빠져나갔다. 핏물이 일어나 사람의 꼴을 이룬다. 혈마가 백 년 만에 눈을 떴다. 교주가 무릎을 꿇고, 호법들이 무릎을 꿇고, 골짜기의 잿빛 가사가 모두 엎드린다. 그날로 혈교는 혈마신교가 되었다. 골짜기 아래의 횃불이 가까워진다.",
   [C("선장을 들고 탈환대를 막으러 내려간다",O("탈환대의 횃불이 꺼졌다. 연못가로 돌아오자 교주가 붉은 가사를 내민다. 호법의 가사다. 받을지 말지는 순례가 다 끝난 뒤에 답하라 한다.",battle="외전_곽승",alignment=AL(m=60),stats={"external":6,"martial":6},full_growth=True,flags=["혈승_부음","혈승_공신"])),
    C("제단 아래 엎드려 경을 외운다",O("경이 끝났을 때 탈환대는 혈위대의 손에 흩어져 있었다. 단전의 빈자리가 식지 않는다.",alignment=AL(m=40),stats={"internal":6,"mind":4},full_growth=True,flags=["혈승_부음"])),
    C("가사를 벗어 제단에 올리고 골짜기를 떠난다",O("아무도 막지 않았다. 교주가 등 뒤에서 말했다. \"죽 한 그릇의 값은 아직 남았다. 네가 알 것이다.\"",alignment=AL(s=40),stats={"mind":8},full_growth=True,flags=["혈승_부음","혈승_벗음"]))]),
  "문":part("제단 쪽에서 교주가 돌아본다. 화난 얼굴이 아니다. \"죽 한 그릇의 값을 그렇게 치르겠다는 것이냐. 좋다. 조각은 두고 가거라. 네 것이 아니다.\" 단전에서 네 조각이 저절로 빠져나가 연못으로 간다. 핏물이 일어난다. 내가 붓지 않아도 강림은 온다.",
   [C("아이들을 데리고 골짜기를 내려간다",O("등 뒤에서 골짜기 전체가 엎드리는 소리가 났다. 돌아보지 않았다. 아이 서른의 발소리가 뒤를 따른다.",stats={"mind":8,"external":4},full_growth=True,flags=["혈승_문"]))])})
story("외전혈승_8",o,110,"강을 따라 내려오는 것",
 "혈마신교의 깃발이 강을 따라 내려온다. 깨어난 것은 날마다 피를 찾고, 교단은 고을마다 공양의 몫을 매긴다. 교주의 영이 내게도 닿았다. 강가 고을 셋에서 공양을 거두어 오라는 것이다. 순례승이 거두면 고을이 덜 버틴다고 한다. 조각을 품었던 몸에서는 아직 그 냄새가 난다.",
 [C("영대로 세 고을의 공양을 거둔다",O("문을 건 집은 없었다. 잿빛 가사 뒤로 줄이 섰다. 돌아오는 배에서 아무도 울지 않았다. 그것이 더 오래 남았다.",alignment=AL(m=80),stats={"internal":8,"external":4},full_growth=True,flags=["혈승_거둠"]),req={"flag":"혈승_부음","not_flag":"혈승_벗음"},hidden=True),
  C("죽 솥을 걸고, 제 발로 따라나서는 자만 데려간다",O("솥 셋을 비우는 동안 따라나선 자는 열이 못 되었다. 몫에는 한참 모자란다. 우호법 반량이 장부를 덮으며 나를 오래 보았다.",alignment=AL(s=60),stats={"mind":8,"internal":4},full_growth=True,flags=["혈승_의심"]),req={"flag":"혈승_부음","not_flag":"혈승_벗음"},hidden=True),
  C("고을에 먼저 알려 배를 띄우게 한다",O("밤사이 세 고을의 배가 하류로 내려갔다. 빈 고을에서 빈 장부를 들고 돌아왔다. 교주는 장부를 받아 들고 아무 말도 하지 않았다. 그 침묵이 영보다 무거웠다.",alignment=AL(j=80),stats={"mind":10,"martial":2},full_growth=True,flags=["혈승_의심","혈승_어김"]),req={"flag":"혈승_부음","not_flag":"혈승_벗음"},hidden=True),
  C("강가 폐사의 문을 걸고 추적대를 기다린다",O("혈위대 조장이 폐사 마당에 쓰러졌다. 아이들이 문틈으로 그것을 보았다. 솥에는 죽이 끓고 있었다.",battle="혈교혈위대",foe="혈위대 추적조장 흑발 도곤",foe_line="\"그릇에 든 것을 들고 달아난 중이 여기 있구나.\"",alignment=AL(j=60),stats={"external":8,"martial":6},full_growth=True,flags=["혈승_추적"]),req={"flag":"혈승_문"},hidden=True),
  C("아이들을 나룻배 셋에 나누어 하류로 보낸다",O("사공들에게 가진 것을 다 털어 주었다. 배 셋이 안개 속으로 내려갔다. 폐사에는 솥 하나와 나만 남았다. 추적대는 빈 절을 뒤지다 돌아갔다.",alignment=AL(j=50),silver=-60,stats={"mind":10,"internal":2},full_growth=True,flags=["혈승_흩음"]),req={"flag":"혈승_문"},hidden=True),
  C("가사 없는 몸으로 공양의 줄 앞을 막아선다",O("공양을 거두던 잿빛 가사들이 선장 아래 흩어졌다. 한때의 도반들이다. 고을 사람들은 고맙다는 말 대신 문을 걸었다. 내 몸에서도 같은 냄새가 났을 것이다.",battle="혈교혈승",foe="공양을 거두는 혈승 적의 무연",foe_line="\"가사를 벗었다고 조각의 냄새가 빠질 줄 알았더냐.\"",alignment=AL(j=60),stats={"external":8,"martial":6},full_growth=True,flags=["혈승_추적"]),req={"flag":"혈승_벗음"},hidden=True),
  C("줄 끝의 굶은 아이에게 죽 한 그릇을 사 준다",O("아이는 죽을 다 비우고도 줄로 돌아갔다. 줄 끝에는 밥이 있다고 들었다는 것이다. 죽 그릇을 받던 날의 내가 그랬다.",alignment=AL(s=40),silver=-10,stats={"mind":12},full_growth=True),req={"flag":"혈승_벗음"},hidden=True)],
 variants=[{"requires":{"flag":"혈승_문"},"text":"혈마신교의 깃발이 강을 따라 내려온다. 깨어난 것은 날마다 피를 찾고, 교단은 고을마다 공양의 몫을 매긴다. 나는 강가 폐사에 솥을 걸고 아이 서른과 숨어 지낸다. 나루의 사공이 일러 준다. 그릇에 든 것을 들고 달아난 중을 찾는 혈위대가 이 물목까지 왔다고."},
  {"requires":{"flag":"혈승_벗음"},"text":"혈마신교의 깃발이 강을 따라 내려온다. 깨어난 것은 날마다 피를 찾고, 교단은 고을마다 공양의 몫을 매긴다. 가사를 벗은 몸으로 강가 고을을 지나는데, 장터에 줄이 섰다. 잿빛 가사들이 공양을 거두고 있다. 줄 끝에 굶은 아이가 서 있다."}])
story("외전혈승_끝",o,120,"죽 한 그릇의 값",
 "십 년째 겨울, 교주가 부른다. 연못가에 좌호법 적발마두 염철이 붉은 머리를 풀고 서 있다. 교주가 말한다. \"깨어나신 분께서 조각이 앉았던 몸을 찾으신다. 네 단전의 빈자리가 식지 않았을 것이다. 둘째 그릇이 되어 연못에 들어라. 순례는 그것으로 끝난다.\" 연못가 우리에는 올해의 공양이 들어 있다.",
 [C("연못에 들어 둘째 그릇이 된다",O("핏물이 정수리까지 찼다. 빈자리에 무엇인가 도로 앉았다. 이번에는 조각이 아니다.",alignment=AL(m=100),ending="외전혈승_공신"),req={"flag":"혈승_부음","not_flag":"혈승_벗음"},hidden=True),
  C("그릇은 되지 않겠다. 잿빛 가사의 순례승으로 남겠다",O("염철이 손을 거두었다. \"네 뜻이 내 손보다 무겁다.\" 교주가 웃었다. \"죽 한 그릇의 값만 치르겠다는 것이냐. 그것도 좋다.\"",battle="외전_염철",spar=True,foe_line="\"영을 물리려면 호법의 손부터 물려라. 교단의 법이다.\"",flags=["혈승_잿빛"],lose_next="끌림",ending="외전혈승_공신"),req={"flag":"혈승_부음","not_flag":"혈승_벗음"},hidden=True),
  C("연못가 우리의 빗장을 내리친다",O("염철이 연못가에 무릎을 꿇었다. 빗장이 부러지고 올해의 공양이 쏟아져 나왔다. 교주는 막지 않았다. 깨어난 것이 연못 속에서 이쪽을 보고 있었다.",battle="외전_염철",foe_line="\"반량이 말했지. 그릇에 든 것에 손대지 말라고.\"",alignment=AL(j=100),ending="외전혈승_파계"),req={"flag":"혈승_의심","not_flag":"혈승_벗음"},hidden=True),
  C("가사를 벗어 연못가에 놓고 떠난다",O("염철이 길을 막으려다 교주의 손짓에 물러섰다. 순례는 끝났고, 죽 한 그릇의 값도 끝났다.",ending="외전혈승_떠돌이"),req={"flag":"혈승_부음","not_flag":"혈승_벗음"},hidden=True),
  C("폐사의 문 앞에 선장을 짚고 선다",O("염철이 폐사 마당에 무릎을 꿇었다. 붉은 머리가 눈 위에 흩어졌다. \"교주께서는... 처음부터 너를 놓아주실 생각이었다. 나는 아니었다.\" 혈마신교는 그 뒤로 이 폐사를 찾지 않았다.",battle="외전_염철",foe_line="\"그릇에 든 것은 그릇으로 돌아간다. 비켜라, 파계승.\"",alignment=AL(j=100),ending="외전혈승_파계"),req={"flag":"혈승_문"},hidden=True),
  C("아이들을 뒷문으로 보내고 홀로 가사를 벗어 내민다",O("염철은 가사를 받아 들고 한참 서 있었다. \"그릇에 든 것 대신 그릇을 가져가라는 것이냐.\" 그는 가사만 들고 돌아갔다. 아이들은 산을 넘었다. 나는 그 뒤를 따르지 못했다.",alignment=AL(s=60),ending="외전혈승_떠돌이"),req={"flag":"혈승_문"},hidden=True),
  C("죽 솥 앞에 서서 공양대를 막는다",O("염철이 솥 앞에 무릎을 꿇었다. \"가사도 없는 놈이... 무엇을 지키겠다고.\" 솥은 엎어지지 않았다. 그날 저녁 고을 아이들이 죽을 먹었다.",battle="외전_염철",foe_line="\"벗은 가사는 다시 입히면 된다. 솥부터 엎어라.\"",alignment=AL(j=100),ending="외전혈승_파계"),req={"flag":"혈승_벗음"},hidden=True),
  C("솥을 지고 강을 건넌다",O("강 건너에는 깃발이 아직 닿지 않았다. 솥은 무거웠고 단전의 빈자리는 여전히 식지 않았다.",ending="외전혈승_떠돌이"),req={"flag":"혈승_벗음"},hidden=True)],
 parts={"끌림":part("염철의 손이 어깨를 눌렀다. \"교단의 법이다. 진 자는 영을 따른다.\" 핏물이 발목에서 무릎으로, 무릎에서 가슴으로 찼다.",
   [C("눈을 감는다",O("빈자리에 무엇인가 도로 앉았다. 이번에는 조각이 아니다.",ending="외전혈승_공신"))])},
 variants=[{"requires":{"flag":"혈승_문"},"text":"십 년째 겨울, 강가 폐사에 눈이 쌓였다. 아이들은 죽 솥 둘레에서 잠들었다. 새벽에 마당의 눈 밟는 소리가 멎는다. 좌호법 적발마두 염철이 붉은 머리를 풀고 홀로 서 있다. \"파계승. 그릇에 든 것을 돌려받으러 왔다. 교주께서는 두라 하셨지만 깨어나신 분의 몫은 내가 챙긴다.\""},
  {"requires":{"flag":"혈승_벗음"},"text":"십 년째 겨울, 강가 고을 장터에 솥을 걸었다. 가사는 없고 솥만 있다. 죽이 끓을 무렵 장터 어귀에 잿빛 가사의 줄이 선다. 혈마신교의 공양대다. 맨 앞에 좌호법 적발마두 염철이 붉은 머리를 풀고 섰다. \"이 고을의 몫을 거두러 왔다. 솥을 치워라. 조각의 냄새가 나는 놈.\""}])
ending("외전혈승_공신",o,"혈마신교의 순례승","강림",10,"〈성명:은/는〉 개조의 의지를 거두어 강림의 밤을 열었고, 끝까지 혈마신교의 중으로 남았다.",[
 F(({"flag":"혈승_잿빛"},"〈그〉는 끝내 연못에 들지 않았다. 호법의 손을 물리고 잿빛 가사로 남은 순례승은 교단에 〈그〉 하나였다."),({}, "연못에서 나온 〈그〉를 교단은 둘째 그릇이라 불렀다. 교단의 아이들은 여전히 조각을 품었던 스님이라 불렀다.")),
 F(({"flag":"혈승_비문"},"덮인 비석의 마지막 줄을 〈그〉는 끝내 읽지 못했다. 첫 피가 누구의 것이었는지. 묻는 것은 경전에 없는 일이다."),({"flag":"혈승_공양"},"강가의 고을은 그 뒤로 잿빛 가사만 보면 문을 걸었다. 〈그〉는 그 고을에 다시 가지 않았다."),({}, "네 곳의 옛 터는 이제 비었다. 우물가의 움막도, 비석이 섰던 자리도.")),
 F(({"flag":"혈승_의심"},"〈그〉는 해마다 흉년 든 고을에 죽 솥을 걸었다. 그 죽에는 피를 넣지 않았다. 교주는 알고도 묻지 않았다."),({}, "〈그〉는 해마다 흉년 든 고을에 죽 솥을 걸었다. 죽에서는 피 냄새가 났고, 굶던 아이 몇이 잿빛 가사를 입었다."))])
ending("외전혈승_파계",o,"죽을 쑤는 중","파계",10,"〈성명:은/는〉 혈마신교의 그릇에 든 아이들 앞을 막아섰다.",[
 F(({}, "혈마는 강림의 밤에 깨어났다. 〈그〉가 막은 것은 강림이 아니라 아이들의 끝이었다.")),
 F(({"flag":"혈승_죽"},"아이들은 〈그〉가 쑤던 죽 맛을 기억했다. 피를 넣지 않은 죽이다."),({}, "아이들은 처음에는 잿빛 가사를 무서워했다. 죽 솥이 걸리고 나서야 가까이 왔다.")),
 F(({}, "〈그〉는 가사를 벗지 않았다. 어느 절도 받아 주지 않았고 혈교도 찾지 않았다. 강가 폐사에 솥을 걸고 흉년마다 죽을 쑤었다.")),
 F(({}, "죽 한 그릇의 값은 죽 한 그릇으로 갚는 것이라고, 〈그〉는 뒷날 아이들에게 말했다."))])
ending("외전혈승_떠돌이",o,"벗어 둔 가사","환속",6,"〈성명:은/는〉 순례를 마치고 가사를 벗었다.",[
 F(({"flag":"혈승_문"},"염철이 들고 간 잿빛 가사는 연못가에 오래 걸려 있었다고 한다."),({}, "벗어 둔 잿빛 가사는 누가 치우지 않아 오래 그 자리에 있었다.")),
 F(({}, "〈그〉의 단전에는 조각이 앉았던 자리가 식지 않고 남았다. 추운 밤이면 그 자리가 먼저 깼다.")),
 F(({}, "어느 고을에서 굶는 아이에게 죽을 사 준 떠돌이가 있었다고 한다. 죽에서 피 냄새는 나지 않았다."))])
rnd("혈승_탁발",[1,2],"잿빛 가사의 탁발",
 "탁발을 나선 마을에서 돌이 날아왔다. 잿빛 가사를 알아본 것이다. \"피 빠는 중이다.\" 어른들이 아이들을 집 안으로 끌어들인다. 문턱에 넘어진 아이 하나의 무릎에서 피가 난다. 단전이 그 냄새에 먼저 답한다.",
 [C("아이의 무릎을 싸매 주고 빈 바리때로 돌아선다",O("아이의 어미가 문틈으로 주먹밥 하나를 굴려 보냈다. 고맙다는 말은 없었다. 주먹밥은 식어 있었다.",alignment=AL(j=50),stats={"mind":5})),
  C("경전대로 피 한 방울을 시주로 청한다",O("아이의 무릎에서 피 한 방울을 찍어 이마에 댔다. 마을이 숨을 죽였다. 그것으로 끝이라는 것을 알고 나서야 누가 쌀을 내왔다.",alignment=AL(m=50),stats={"internal":5})),
  C("돌 던진 자에게 바리때를 내민다",O("그는 돌 대신 엽전을 넣었다. 손이 떨렸다. 무서워서 주는 시주도 시주다.",alignment=AL(s=40),silver=30,stats={"external":2}))],origin=o)
rnd("혈승_경전",[2,3],"경전의 다음 권",
 "본산에서 온 혈승이 보따리를 내려놓는다. \"교주께서 보내셨다. 조각을 품은 몸은 첫 권의 호흡으로는 버티지 못한다고.\" 피로 쓴 경전의 다음 권이다. 글자가 아직 마르지 않은 것 같다.",
 [C("그 자리에서 펴 읽는다",O("혈마심공이다. 호흡이 바뀌자 단전의 조각이 조용해졌다. 길들여진 것인지 숨은 것인지는 모르겠다.",skill="혈마심공",stats={"internal":4})),
  C("누구의 피로 썼는지 묻고 읽는다",O("\"자원한 신도들이다.\" 혈승의 대답은 빨랐다. 너무 빨랐다. 그래도 폈다. 혈마심공이다.",skill="혈마심공",stats={"mind":4},flags=["혈승_의심"]))],origin=o,req={"no_skill":"혈마심공","sect":"혈교"})

o="외전야수"
story("서장_외전야수",o,1,"범의 젖",
 "야수궁의 아이들은 짐승 곁에서 자란다. 나는 늙은 암범의 젖을 먹었고, 늙은 권사들에게 백수권을 배워 궁의 아이들 가운데 가장 센 주먹이 되었다. 그 범이 어제 죽었다. 대술사 만독왕 아루타가 범의 가죽을 벗기라 이르고는 나를 본다. \"만수왕의 자리가 빈 지 한 세대다. 다섯 영물과 맹약을 맺은 자만 만수전의 문을 연다. 궁의 아이 가운데 짐승의 뜻을 알아듣는 것은 너 하나다. 중원의 산으로 가거라. 맹약을 맺어 오면 왕좌는 네 것이고, 궁은 내가 지금처럼 맡으마.\" 그의 소매에서 붉은 실로 묶은 서찰이 삐져나와 있다.",
 [C("젖어미를 가죽째 묻어 주고 떠난다",O("술사들이 수군거렸다. 궁에서는 가죽을 벗기는 것이 예다. 흙을 덮고 그 위에서 하룻밤을 잤다.",alignment=AL(j=20),stats={"mind":1})),
  C("가죽은 궁의 것이니 값을 쳐 달라 한다",O("대술사가 웃으며 은자를 던져 주었다. \"셈을 아는구나. 왕이 될 만하다.\"",alignment=AL(s=20),silver=20)),
  C("젖어미의 가죽을 내가 걸치고 떠난다",O("가죽은 따뜻했다. 야수궁에서는 그것이 가장 큰 효다.",alignment=AL(m=20),stats={"external":1}))])
story("외전야수_2",o,25,"산군의 약조",
 "태항산의 산군 백액호를 찾았다. 이마에 흰 줄이 난 범이 바위 위에서 나를 내려다본다. 사람의 말은 하지 않지만 뜻은 들린다. 사냥꾼들이 새끼를 잡아갔다. 찾아오면 약조하겠다. 산 아래 장터에는 새끼 범을 우리에 넣고 값을 부르는 사냥꾼 패가 있다. 그 뒤에 붉은 소매 하나가 섞여 서 있다.",
 [C("사냥꾼 패를 쫓아내고 새끼를 돌려준다",O("산군이 새끼의 목덜미를 물어 올리고 내 손등을 한 번 핥았다. 손등에 흰 줄이 남았다. 첫 맹약이다. 붉은 소매는 어느새 보이지 않았다.",battle="무명사냥꾼",foe="태항의 범 사냥꾼 패",foe_line="\"남만 촌것이 남의 장사를 망치네. 가죽이 둘로 늘겠다.\"",alignment=AL(j=50),stats={"external":4,"martial":3},fame=10)),
  C("값을 치르고 새끼를 산다",O("사냥꾼들은 은자를 세며 웃었다. 산군은 새끼를 받고 내 손등을 한 번 핥았다. 흰 줄이 남았다. 첫 맹약이다.",alignment=AL(s=30),silver=-80,stats={"mind":3}),req={"min_silver":80}),
  C("새끼를 미끼로 산군을 엎드리게 한다",O("우리를 벼랑 끝에 걸었다. 산군은 엎드렸다. 손등에 흰 줄이 남았지만, 범의 눈은 끝내 나를 보지 않았다.",alignment=AL(m=70),stats={"external":5},flags=["야수_억지"]))])
story("외전야수_3",o,49,"빈 둥지",
 "금안신조의 둥지는 비어 있었다. 깃털과 피, 그리고 가슴을 가른 자국. 내단을 꺼내 간 것이다. 불가사리의 굴도, 천년 백사의 못도 그랬다. 굴마다 붉은 실 한 오라기가 떨어져 있다. 신교의 내단 사냥꾼들이다. 빈 둥지 구석에서 눈도 못 뜬 새끼 신조 한 마리가 운다.",
 [C("새끼를 품에 넣고 기른다",O("석 달을 씹어 먹였다. 새끼가 처음 난 날 내 어깨에 발톱 자국을 남겼다. 둘째 맹약이다.",alignment=AL(j=60),stats={"mind":5,"internal":3})),
  C("사냥꾼들의 뒤를 밟아 어미의 내단을 되찾는다",O("되찾은 내단을 새끼 앞에 놓았다. 새끼가 그것을 품고 잠들었다. 깨어나서는 내 어깨에 앉았다. 둘째 맹약이다.",battle="마교암살귀",foe="내단 사냥꾼 조장 흑아",foe_line="\"남만의 개가 주인 일에 끼어드나. 너희 대술사가 길을 일러 줬는데.\"",alignment=AL(m=30,j=30),stats={"external":5,"martial":5},flags=["야수_대술사"])),
  C("새끼를 궁으로 보내 대술사에게 맡긴다",O("대술사는 값을 후하게 쳐 보냈다. 새끼가 어찌 되었는지는 답장에 적혀 있지 않았다.",alignment=AL(s=40),silver=100,flags=["야수_깨짐"]))])
story("외전야수_4",o,73,"대술사의 수레",
 "남만으로 내려가는 길목에서 궁의 수레 행렬을 만났다. 우리마다 영물이 실려 있다. 맹약의 표식이 없는, 억지로 잡은 것들이다. 행렬을 이끄는 것은 고술사 홍사 아라다. \"대술사님의 명이다. 신교가 내단 하나에 독충 천 근 값을 쳐 준다. 궁이 살려면 팔아야지. 왕좌에 앉을 분이 그것도 모르시나.\" 맨 끝 우리에서 철갑 현귀가 느리게 눈을 뜬다. 뜻이 들린다. 풀어 주면 약조하겠다.",
 [C("수레를 부수고 영물들을 푼다",O("우리가 열리자 영물들은 뒤도 돌아보지 않고 흩어졌다. 현귀만 남아 등딱지를 내 손바닥에 댔다. 셋째 맹약이다. 궁에는 이제 편히 돌아갈 수 없을 것이다.",battle="남만술사",foe="고술사 홍사 아라",foe_line="\"짐승 편을 드는 왕은 필요 없다. 대술사님께 그리 아뢰마.\"",alignment=AL(j=60),stats={"external":6,"internal":5},fame=20,flags=["야수_수레"])),
  C("현귀 하나만 값을 치르고 빼낸다",O("아라는 은자를 받고 우리 하나를 열었다. 나머지 수레는 북쪽으로 갔다. 현귀가 등딱지를 내 손바닥에 댔다. 셋째 맹약이다. 다른 우리의 눈들은 보지 않았다.",alignment=AL(s=50),silver=-200,stats={"mind":4}),req={"min_silver":200}),
  C("수레를 지켜 주며 대술사의 셈을 배운다",O("내단 하나에 독충 천 근. 독충 천 근이면 고을 하나. 셈은 어렵지 않았다. 현귀의 눈이 수레가 멀어질 때까지 나를 보았다.",alignment=AL(m=60),silver=200,stats={"martial":5},flags=["야수_깨짐"]))])
story("외전야수_5",o,97,"남은 것들의 청",
 "신교의 사냥이 산을 다 훑었다. 살아남은 영물들이 먼저 나를 찾아온다. 산신의 사자 백록이 안개 속에서 걸어 나오고, 그 뒤로 해치가 뿔을 낮춘다. 뜻은 하나다. 왕이 있어야 한다. 사람과 짐승 사이에 서서 약조를 지키게 할 왕이. 백록의 뿔에는 사냥꾼의 그물 조각이 걸려 있다.",
 [C("두 영물과 맹약을 맺는다",
    O("백록이 뿔로 내 가슴을 짚었다. 해치는 뿔을 겨눈 채 한참 나를 재었다. 그러다 뿔을 내렸다. 왕이 없는 것보다는 낫다는 뜻이다. 넷째와 다섯째다.",req={"dominant":"마도"},stats={"mind":6,"internal":6},full_growth=True),
    O("백록이 뿔로 내 가슴을 짚고 해치가 이마를 맞댔다. 넷째와 다섯째다. 해치는 시비를 가리는 짐승이라, 맹약을 맺으며 내 지난 일을 다 들여다보았다. 그래도 물러서지 않았다.",req={"not_dominant":["마도"]},alignment=AL(j=60),stats={"mind":8,"internal":6},full_growth=True)),
  C("맹약에 앞서 사냥을 이끄는 자부터 쫓는다",O("사냥개가 쓰러지자 산이 조용해졌다. 백록과 해치가 다가와 말없이 맹약을 내밀었다. 넷째와 다섯째다.",battle="천마사냥개",foe_line="\"내단 냄새가 나는구나. 네 것도 꺼내 가마.\"",alignment=AL(m=50),stats={"external":8,"martial":8},full_growth=True,flags=["야수_사냥개"])),
  C("두 영물의 뿔 값을 속으로 셈해 본다",O("뿔에 손을 대지는 않았다. 다만 셈을 했다는 것을 해치는 알았다. 안개가 걷혔을 때 둘은 없었다.",alignment=AL(s=40,m=40),stats={"martial":6},full_growth=True,flags=["야수_깨짐"]))])
story("외전야수_끝",o,120,"만수전",
 "남만 야수궁의 가장 깊은 곳. 만수전의 돌문은 한 세대 동안 열리지 않았다. 문 앞에 대술사 만독왕 아루타와 궁의 술사들이 늘어섰다. 문 위 들보에는 흰 원숭이 한 마리가 앉아 있다. 왕좌를 지키는 영물 백공이다. 대술사가 말한다. \"다섯 맹약을 맺어 왔느냐. 그렇다면 문지기가 알아볼 것이다. 아니라면 여기서 내게 절하고 궁의 사냥꾼으로 살아라.\" 흰 원숭이가 들보에서 내려와 내 손등을 들여다본다.",
 [C("다섯 맹약을 내보이고 문지기의 시험을 받는다",O("백공이 긴 팔을 거두고 돌문 옆으로 비켜 앉았다. 돌문이 저절로 열린다.",battle="외전_백공",spar=True,next="왕좌",lose_next="문밖"),req={"not_flag":"야수_깨짐"},hidden=True),
  C("맹약이 모자라도 힘으로 문지기를 꺾는다",O("백공이 문 앞에 쓰러졌다. 돌문을 어깨로 밀어 열었다.",battle="외전_백공",alignment=AL(m=60),next="빈왕좌"),req={"flag":"야수_깨짐"},hidden=True),
  C("문 앞에서 돌아선다",O("대술사가 뒤에서 무어라 불렀다. 돌아보지 않았다.",ending="외전야수_숲"))],
 parts={
  "왕좌":part("짐승 가죽을 깐 돌 의자 하나. 백공이 의자 옆에 앉는다. 등 뒤에서 대술사가 묻는다. \"왕이시여. 신교와의 약조는 어찌하오리까. 궁은 그 값으로 삽니다.\"",
   [C("신교와의 약조를 끊는다. 영물은 궁의 벗이다",O("대술사의 얼굴이 굳었다. 술사 몇은 고개를 숙였고 몇은 숨을 내쉬었다.",alignment=AL(j=60),ending="외전야수_만수왕")),
    C("약조는 잇되 영물은 내주지 않는다. 값은 다른 것으로 치른다",O("대술사가 천천히 절했다. \"셈을 아는 왕이시군요.\"",alignment=AL(s=60),flags=["야수_줄타기"],ending="외전야수_만수왕")),
    C("왕좌를 비워 두고 영물들과 산으로 간다",O("백공이 처음으로 소리를 냈다. 웃음 같았다.",ending="외전야수_숲"))]),
  "문밖":part("백공의 긴 팔이 내 목 앞에서 멈췄다. 흰 원숭이가 고개를 젓는다. 맹약은 족하나 몸이 아직 왕의 것이 아니라는 뜻이다.",
   [C("영물들과 산으로 돌아가 때를 기다린다",O("대술사는 웃었지만, 술사 몇은 내 등에 대고 절했다.",ending="외전야수_숲"))]),
  "빈왕좌":part("왕좌는 차갑다. 궁의 술사들이 절한다. 궁 안의 짐승들은 하나도 절하지 않는다.",
   [C("앉는다",O("돌 의자의 가죽에서는 아무 냄새도 나지 않았다.",ending="외전야수_폭군"))])})
enemy("외전_백공","십대고수",hp=25000,attack=292,armor=24,name="백공",title="만수전을 지키는 흰 원숭이",desc="야수궁의 왕좌를 지키는 영물. 다섯 맹약의 표식을 알아보고, 표식의 주인이 왕의 몸을 갖추었는지 긴 팔로 잰다.",
 intro="흰 원숭이가 손등의 표식을 하나씩 짚어 세더니 긴 팔을 늘어뜨린다.",outro="백공이 돌문 앞에 쓰러졌다. 들보 위의 먼지가 한꺼번에 내려앉았다.",spar_outro="백공이 긴 팔을 거두고 돌문 옆으로 비켜 앉았다.",
 specials=[{"name":"통비권","every":3,"mult":2.2},{"name":"포효","every":5,"mult":1.5,"seal":1}],
 phases=[{"hp_pct":45,"attack_mult":1.2,"text":"백공의 흰 털이 곤두선다. 들보와 기둥을 차며 사방에서 팔이 날아온다.","specials":[{"name":"통비권","every":2,"mult":1.9},{"name":"포효","every":5,"mult":1.5,"seal":1}]}])
ending("외전야수_만수왕",o,"만수왕","만수",12,"〈성명:은/는〉 다섯 영물의 맹약으로 만수전의 문을 열고 한 세대 만에 만수왕의 자리에 앉았다.",[
 F(({"flag":"야수_줄타기"},"신교의 사자는 그 뒤로도 궁에 왔다. 독충은 실어 갔지만 우리는 빈 채로 돌아갔다."),({}, "신교의 사자가 붉은 실로 묶은 서찰을 들고 왔다가 돌문 앞에서 돌아갔다. 문지기가 길을 내주지 않았다.")),
 F(({"flag":"야수_억지"},"산군은 약조를 지켰다. 다만 왕좌 곁에 앉는 일은 없었다. 벼랑 끝의 우리를 범은 잊지 않는다."),({"flag":"야수_수레"},"수레에서 풀려난 영물들이 해마다 한 번 남만의 숲 가장자리까지 내려왔다. 궁의 아이들은 그날을 명절로 쳤다."),({}, "산군과 신조와 현귀, 백록과 해치. 다섯의 표식은 〈그〉의 손등에서 죽는 날까지 지워지지 않았다.")),
 F(({"flag":"야수_사냥개"},"사냥개가 쓰러진 산에는 이듬해 봄 새끼들이 태어났다."),({}, "빈 둥지와 빈 굴이 다시 차는 데는 오래 걸렸다. 〈그〉는 그 수를 해마다 셌다.")),
 F(({}, "대술사 아루타는 궁의 살림을 계속 맡았다. 다만 우리의 열쇠는 왕좌 옆 흰 원숭이의 목에 걸렸다."))])
ending("외전야수_숲",o,"산으로 간 아이","귀산",7,"〈성명:은/는〉 왕좌에 앉지 않고 영물들과 산으로 갔다.",[
 F(({"flag":"야수_깨짐"},"깨진 약조는 다시 맺기 어렵다. 〈그〉는 빈 굴마다 먹이를 두고 다녔다. 받아 가는 것이 있는지는 보지 않았다."),({}, "손등의 표식을 알아보는 짐승들이 산마다 길을 내주었다.")),
 F(({}, "만수왕의 자리는 한 세대 더 비었다. 대술사는 궁을 맡았고, 수레는 북쪽으로 갔다.")),
 F(({}, "남만의 사냥꾼들은 깊은 산에서 범의 가죽을 걸친 사람을 보았다고 했다. 범 여럿과 함께였다고."))])
ending("외전야수_폭군",o,"짐승 없는 왕","공왕",8,"〈성명:은/는〉 맹약 없이 문지기를 꺾고 만수왕의 자리에 앉았다.",[
 F(({}, "술사들은 절했고 사냥꾼들은 따랐다. 궁의 우리는 전보다 더 찼다.")),
 F(({}, "〈그〉가 지나가면 궁 안의 짐승들이 울음을 그쳤다. 어릴 때는 그 뜻이 들렸는데, 왕좌에 앉고부터는 들리지 않았다.")),
 F(({}, "젖어미의 무덤 자리에는 풀이 났다. 〈그〉는 그 앞을 지날 때만 걸음이 느려졌다고 한다."))])
